//! 🎞️ Original image frames, samples and metadata retain genuine scalar relationship custody.
use super::{SemioImageSnapshot,SemioColorspace,SemioImageFrame,SemioImageMetadataEntry,identity,number};
use store::{ArtifactSqliteSnapshot,sqlite_snapshot::{SqliteDatabase,SqliteSnapshotControl,SqliteSnapshotPhase,SqliteValue,artifact::{RowIdentity,RowIndex,RowIndexStorage,reconstruct_text_into,reconstruct_blob_into},transfer::{SchemaValidationStorage,validate_database_into,validate_component_into,reserve}}};
use semio_framework_value::{ValueError,ValueRefusalKind};
#[derive(semio_framework_value::RetireOwned)]
struct Prefix{snapshot:Option<SemioImageSnapshot>,validation:SchemaValidationStorage,frames:RowIndexStorage,metadata:RowIndexStorage,samples:RowIndexStorage,frame_order:Vec<usize>,metadata_order:Vec<usize>,sample_order:Vec<usize>}
fn empty()->Prefix{Prefix{snapshot:Some(super::native_decoding::empty()),validation:SchemaValidationStorage::empty(),frames:RowIndexStorage::empty(),metadata:RowIndexStorage::empty(),samples:RowIndexStorage::empty(),frame_order:Vec::new(),metadata_order:Vec::new(),sample_order:Vec::new()}}
fn invalid(message:&'static str)->ValueError{ValueError::literal(ValueRefusalKind::InvalidValue,message)}
pub(super)fn reconstruct(database:&SqliteDatabase,control:&mut SqliteSnapshotControl<'_>,declared:&str)->Result<SemioImageSnapshot,ValueError>{crate::standards::v1::subsets::base::io::sqlite::snapshot::native_decoding::workspace::reconstruct_projected(control,empty,|prefix,control|{
 let phase=SqliteSnapshotPhase::ReconstructSnapshot;control.check_database(database,phase)?;validate_database_into(&mut prefix.validation,database,declared,phase,control)?;validate_component_into(&mut prefix.validation,database,SemioImageSnapshot::SQLITE_SCHEMA,phase,control)?;let document=database.table("semio_image_document")?.single_row()?;identity(document,7)?;if document.rowid!=1{return Err(invalid("invalid Semio image document identifier"))}let snapshot=prefix.snapshot.as_mut().unwrap();snapshot.width=u32::try_from(document.integer(2)?).map_err(|_|invalid("invalid Semio image width"))?;snapshot.height=u32::try_from(document.integer(3)?).map_err(|_|invalid("invalid Semio image height"))?;snapshot.bit_depth=u8::try_from(document.integer(5)?).map_err(|_|invalid("invalid Semio image bit depth"))?;snapshot.colorspace=match document.text(4)?{"rgb"=>SemioColorspace::Rgb,"rgba"=>SemioColorspace::Rgba,"grayscale"=>SemioColorspace::Grayscale,"grayscale_alpha"=>SemioColorspace::GrayscaleAlpha,"indexed"=>SemioColorspace::Indexed,_=>return Err(invalid("unknown Semio image colorspace"))};match &document.values[6]{SqliteValue::Null=>{},SqliteValue::Blob(bytes)=>{snapshot.icc=Some(Vec::new());reconstruct_blob_into(snapshot.icc.as_mut().unwrap(),control,bytes)?;},_=>return Err(invalid("invalid Semio image ICC storage class"))}
 let frames=RowIndex::new_with_identity(&mut prefix.frames,database,"semio_image_frame",4,&[],RowIdentity::Signed,control,"invalid Semio image frame identity")?;let metadata=RowIndex::new_with_identity(&mut prefix.metadata,database,"semio_image_metadata",5,&[],RowIdentity::Signed,control,"invalid Semio image metadata identity")?;let samples=RowIndex::new_with_identity(&mut prefix.samples,database,"semio_image_sample",5,&[],RowIdentity::Signed,control,"invalid Semio image sample identity")?;frames.ordered_into(&mut prefix.frame_order,2,control,"Semio image ordinals require contiguous occurrences")?;metadata.ordered_into(&mut prefix.metadata_order,2,control,"Semio image ordinals require contiguous occurrences")?;
 for(count,&index)in samples.indices().iter().enumerate(){let row=samples.row(index)?;if frames.get(row.integer(1)?,control)?.is_none(){return Err(invalid("orphan Semio image sample"))}control.checkpoint(phase,count+1,samples.len())?;}samples.grouped_by_into(&mut prefix.sample_order,2,control,"invalid Semio image sample ordinal",|row|Ok((0,Some(row.integer(1)?))))?;snapshot.frames=reserve(prefix.frame_order.len(),control)?;let mut completed=0;
 for &index in &prefix.frame_order{let row=frames.row(index)?;if row.integer(1)?!=1{return Err(invalid("invalid Semio image frame ownership"))}let range=samples.range_by(&prefix.sample_order,(0,Some(row.rowid)),control,|row|Ok((0,Some(row.integer(1)?))))?;snapshot.frames.push(SemioImageFrame{delay_ms:0,rgba8:Vec::new()});let frame=snapshot.frames.last_mut().unwrap();frame.rgba8=reserve(range.len(),control)?;for(ordinal,position)in range.enumerate(){let sample=samples.row(prefix.sample_order[position])?;if sample.integer(2)?!=number(ordinal)?||sample.integer(3)?!=number(ordinal%4)?{return Err(invalid("invalid Semio image sample ordinal or channel"))}frame.rgba8.push(u8::try_from(sample.integer(4)?).map_err(|_|invalid("invalid Semio image sample octet"))?);completed+=1;if completed%256==0{control.checkpoint(phase,completed,samples.len())?;}}frame.delay_ms=u32::try_from(row.integer(3)?).map_err(|_|invalid("invalid Semio image frame delay"))?;
 }if completed!=samples.len(){return Err(invalid("unconsumed Semio image sample"))}snapshot.metadata=reserve(prefix.metadata_order.len(),control)?;for &index in &prefix.metadata_order{let row=metadata.row(index)?;if row.integer(1)?!=1{return Err(invalid("invalid Semio image metadata ownership"))}snapshot.metadata.push(SemioImageMetadataEntry{key:String::new(),value:String::new()});let entry=snapshot.metadata.last_mut().unwrap();reconstruct_text_into(&mut entry.key,control,row.text(3)?)?;reconstruct_text_into(&mut entry.value,control,row.text(4)?)?;completed+=1;if completed%256==0{control.checkpoint(phase,completed,0)?;}}reconstruct_text_into(&mut snapshot.schema,control,document.text(1)?)?;control.checkpoint(phase,completed,completed)
},|prefix|prefix.snapshot.take().unwrap())}
